package au.com.shiftyjelly.pocketcasts.repositories.ads.text

import java.text.Normalizer
import java.util.Locale
import java.util.regex.Pattern
import kotlin.math.ln
import kotlin.math.sqrt

/**
 * Reproduces scikit-learn's `TfidfVectorizer` for the two analyzers in the bundle
 * (`word` 1-2 grams and `char_wb` 3-5 grams) and the fitted logistic classifier.
 *
 * The parity contract is tested against fixtures generated by the Python trainer.
 */
internal class TfidfTextVectorizer(bundle: AdDetectorBundle) {
    private val word = Block(bundle.word)
    private val char = Block(bundle.char)
    private val weights = bundle.classifier.weights.toDoubleArray()
    private val intercept = bundle.classifier.intercept
    private val prior = bundle.classifier.positivePrior.coerceIn(0.01, 0.99)

    fun score(document: String): Double {
        val text = preprocess(document)
        val vector = SparseVector()
        word.addFeatures(text, vector, isWord = true)
        char.addFeatures(text, vector, isWord = false)
        return adjustLogistic(vector.dot(weights) + intercept)
    }

    /** Balanced training restores the observed positive prior before the decoder threshold. */
    private fun adjustLogistic(raw: Double): Double {
        val clipped = raw.coerceIn(-30.0, 30.0)
        val probability = 1.0 / (1.0 + Math.exp(-clipped))
        val safe = probability.coerceIn(1e-6, 1.0 - 1e-6)
        val logit = ln(safe / (1.0 - safe)) + ln(prior / (1.0 - prior))
        return 1.0 / (1.0 + Math.exp(-logit.coerceIn(-30.0, 30.0)))
    }

    private class Block(private val spec: AdDetectorBundle.FeatureBlock) {
        private val index = HashMap<String, Int>(spec.vocab.size * 2)
        private val idf = spec.idf.toDoubleArray()
        private val offset = spec.offset
        private val sublinear = spec.sublinearTf
        private val minN = spec.ngram.firstOrNull() ?: 1
        private val maxN = spec.ngram.lastOrNull() ?: minN

        init {
            spec.vocab.forEachIndexed { i, token -> index[token] = i }
        }

        fun addFeatures(text: String, out: SparseVector, isWord: Boolean) {
            val counts = HashMap<Int, Int>()
            val tokens = if (isWord) TfidfTextVectorizer.wordNgrams(text, minN, maxN) else TfidfTextVectorizer.charWbNgrams(text, minN, maxN)
            for (token in tokens) {
                val local = index[token] ?: continue
                counts[local] = (counts[local] ?: 0) + 1
            }
            if (counts.isEmpty()) return
            val values = HashMap<Int, Double>(counts.size * 2)
            var norm = 0.0
            for ((local, count) in counts) {
                val tf = if (sublinear) 1.0 + ln(count.toDouble()) else count.toDouble()
                val value = tf * idf[local]
                values[local] = value
                norm += value * value
            }
            if (norm <= 0.0) return
            val scale = sqrt(norm)
            for ((local, value) in values) out.add(offset + local, value / scale)
        }
    }

    private class SparseVector {
        private var indices = IntArray(16)
        private var values = DoubleArray(16)
        private var size = 0

        fun add(index: Int, value: Double) {
            if (size == indices.size) {
                indices = indices.copyOf(size * 2)
                values = values.copyOf(size * 2)
            }
            indices[size] = index
            values[size] = value
            size++
        }

        fun dot(weights: DoubleArray): Double {
            var sum = 0.0
            for (i in 0 until size) {
                val idx = indices[i]
                if (idx < weights.size) sum += weights[idx] * values[i]
            }
            return sum
        }
    }

    companion object {
        private const val WORD_PATTERN = "\\b\\w\\w+\\b"
        private val wordPattern = Pattern.compile(WORD_PATTERN, Pattern.UNICODE_CHARACTER_CLASS)
        private val whitespace = Regex("\\s+")

        /** sklearn's strip_accents="unicode" followed by lowercasing. */
        fun preprocess(text: String): String {
            val decomposed = Normalizer.normalize(text, Normalizer.Form.NFKD)
            val stripped = buildString(decomposed.length) {
                for (ch in decomposed) {
                    if (Character.getType(ch) != Character.NON_SPACING_MARK.toInt()) append(ch)
                }
            }
            return stripped.lowercase(Locale.ROOT)
        }

        fun wordNgrams(text: String, minN: Int, maxN: Int): Sequence<String> = sequence {
            val tokens = ArrayList<String>()
            val matcher = wordPattern.matcher(text)
            while (matcher.find()) tokens.add(matcher.group())
            for (n in minN..maxN) {
                if (n <= 0) continue
                for (i in 0..tokens.size - n) {
                    yield(tokens.subList(i, i + n).joinToString(" "))
                }
            }
        }

        /** sklearn's `_char_wb_ngrams`: pad each whitespace-separated word and take n-grams. */
        fun charWbNgrams(text: String, minN: Int, maxN: Int): Sequence<String> = sequence {
            for (word in text.split(whitespace)) {
                if (word.isEmpty()) continue
                val padded = " $word "
                for (n in minN..maxN) {
                    var offset = 0
                    yield(padded.substring(0, minOf(n, padded.length)))
                    while (offset + n < padded.length) {
                        offset++
                        yield(padded.substring(offset, offset + n))
                    }
                    if (offset == 0) break
                }
            }
        }
    }
}
